def add_heads(apps, schema_editor):
    RevenueHead = apps.get_model("finance", "RevenueHead")
    if not RevenueHead.objects.exists():
        return          # a fresh database is filled by seed_council
    line = getattr(RevenueHead.objects.filter(code="BUILD-PLAN").first(), "budget_line", None)
    for code, name, cat, amount in HEADS:
        RevenueHead.objects.get_or_create(code=code, defaults=dict(name=name, category=cat, default_amount=amount, frequency="ONCE", budget_line=line))


